package org.sparkcorporation.lims.order.api;

import java.util.regex.Pattern;

import jakarta.persistence.Embeddable;

/**
 * Typed business-key daily-ID for a Sample — {@code <prefix><ddMMyy>-<seq>}, where {@code prefix}
 * is the 1..5 {@code DisciplinePrefix} numeric value and {@code seq} is a per-(day, prefix)
 * three-digit sequence. CDC §IV. Generated by {@code DefaultSampleDailyIdGenerator}.
 *
 * <p>Annotated {@code @Embeddable} so it can be embedded into the {@code Sample} aggregate via
 * {@code @Embedded} + {@code @AttributeOverride(name = "value", column = ...)}.
 */
@Embeddable
public record SampleDailyId(String value) {

    private static final Pattern FORMAT = Pattern.compile("^[12345]\\d{6}-\\d{3}$");

    public SampleDailyId {
        if (value == null || !FORMAT.matcher(value).matches()) {
            throw new IllegalArgumentException("invalid daily id: " + value);
        }
    }
}
